window.ANSWER_TERMS = {"ATP":{"match":"adenosinetrifosfaat|adenosine trifosfaat|adenosine-trifosfaat|ATP","title":"ATP (adenosinetrifosfaat)","short":"ATP is de energiemunt van de cel: bij afsplitsing van de derde fosfaatgroep komt energie vrij die transport, contractie en biosynthese aandrijft.","definition":"<p><strong>ATP</strong> (adenosinetrifosfaat) bestaat uit adenine, ribose en drie fosfaatgroepen. Hydrolyse van de eindstandige fosfaatbinding (ATP → ADP + P<sub>i</sub>) levert ongeveer 30 kJ/mol — genoeg om ongunstige reacties te koppelen aan een gunstige: spiercontractie, de Na⁺/K⁺-ATPase, en de opbouw van eiwitten, vetten en DNA.</p><p>Het meeste ATP komt uit de <em>oxidatieve fosforylering</em> in het mitochondrion: de elektronentransportketen pompt protonen naar de intermembraanruimte, en ATP-synthase laat die protonengradiënt terugstromen en maakt daarmee ATP (chemiosmose). Glycolyse en de citroenzuurcyclus leveren daarnaast rechtstreeks een kleine hoeveelheid.</p><p>De cel slaat ATP nauwelijks op — de voorraad gaat in seconden — dus productie en verbruik zijn strak gekoppeld: veel ADP versnelt de verbranding, overmaat ATP remt die af.</p>","image_url":"","wiki_titles":["Adenosine triphosphate","ATP synthase"]},"cholesterol":{"title":"Cholesterol","short":"Vetachtige stof die de celmembraan stevigheid en de juiste vloeibaarheid geeft en grondstof is voor steroïden.","definition":"<p><b>Cholesterol</b> is een steroïd dat tussen de fosfolipiden van de celmembraan zit en de membraanvloeibaarheid stabiliseert.</p><p>Het is bovendien de grondstof voor steroïdhormonen, vitamine D en galzouten.</p>","image_url":"","wiki_title":"Cholesterol","match":"cholesterol"},"necrose":{"title":"Necrose","short":"Ongecontroleerde celdood door schade, waarbij de cel opzwelt, openbarst en een ontstekingsreactie uitlokt.","definition":"<p><b>Necrose</b> is celdood door acute schade (zuurstoftekort, toxinen, trauma). De cel zwelt op en de membraan scheurt.</p><p>De vrijkomende celinhoud lokt een ontstekingsreactie uit — anders dan bij de 'nette' apoptose.</p>","image_url":"","wiki_title":"Necrosis","match":"necrose"},"macula":{"title":"Macula","short":"Vlakke, niet-voelbare huidverandering die alleen in kleur verschilt (een 'vlek').","definition":"<p>Een <b>macula</b> is een plat, met de vinger niet-voelbaar plekje dat zich alleen door kleur onderscheidt van de omgeving.</p><p>Voorbeelden zijn een sproet of een café-au-lait-vlek. Wordt hij groter dan ~1 cm, dan spreekt men van een patch.</p>","image_url":"","wiki_title":"Skin condition","match":"macula|maculae"},"plaque":{"title":"Plaque","short":"Verheven, plateauvormige huidafwijking groter dan ~1 cm, vaak door samenvloeien van papels.","definition":"<p>Een <b>plaque</b> is een verheven, afgeplatte laesie groter dan ongeveer 1 cm — breder dan hoog.</p><p>Ze ontstaat vaak door het samenvloeien van papels en is typisch voor psoriasis.</p>","image_url":"","wiki_title":"Skin condition","match":"plaque|plaques"},"nodulus":{"title":"Nodulus","short":"Vaste, verheven en voelbare knobbel die dieper in de huid reikt dan een papel (> ~1 cm).","definition":"<p>Een <b>nodulus</b> (nodus, knobbel) is een stevige, verheven laesie die groter is dan een papel en dieper in de dermis of subcutis reikt.</p><p>Voorbeelden zijn een dermatofibroom of sommige huidtumoren.</p>","image_url":"","wiki_title":"Nodule (medicine)","match":"nodulus|nodus|noduli|nodi"},"erosie":{"title":"Erosie","short":"Oppervlakkig huiddefect beperkt tot de epidermis, dat zonder litteken geneest.","definition":"<p>Een <b>erosie</b> is een oppervlakkig verlies van epidermis, bijvoorbeeld nadat een blaasje is opengegaan.</p><p>Omdat de dermis intact blijft, geneest een erosie zonder litteken.</p>","image_url":"","wiki_title":"Erosion (dermatology)","match":"erosie|erosies"},"ulcus":{"title":"Ulcus","short":"Diep huiddefect tot in de dermis of dieper, dat met een litteken geneest (een 'zweer').","definition":"<p>Een <b>ulcus</b> (zweer) is een dieper weefselverlies dat tot in de dermis of subcutis reikt.</p><p>Doordat de dermis is aangetast, geneest het met littekenvorming. Een ulcus cruris (open been) is een bekend voorbeeld.</p>","image_url":"","wiki_title":"Ulcer (dermatology)","match":"ulcus|ulcera"},"atrofie":{"title":"Atrofie","short":"Verdunning of afname van weefsel; bij de huid een dunnere, kwetsbaardere epidermis en/of dermis.","definition":"<p><b>Atrofie</b> is het slinken van een weefsel of orgaan doordat de cellen krimpen of in aantal afnemen.</p><p>Huidatrofie (bijv. na langdurig sterk corticosteroïdgebruik of door veroudering) geeft een dunne, doorschijnende, kwetsbare huid.</p>","image_url":"","wiki_title":"Atrophy","match":"atrofie"},"hypertensie":{"title":"Hypertensie","short":"Hypertensie is een blijvend verhoogde bloeddruk (≥140/90 mmHg op het spreekuur); een belangrijke risicofactor voor hart- en vaatziekten.","definition":"<p>Bij <strong>hypertensie</strong> is de bloeddruk herhaaldelijk verhoogd: op het spreekuur ≥140/90 mmHg. Meestal is er geen aanwijsbare oorzaak (<em>primaire/essentiële</em> hypertensie); bij een minderheid is er een secundaire oorzaak, zoals nierziekte, nierarteriestenose, hyperaldosteronisme of feochromocytoom.</p><p>Hypertensie geeft meestal geen klachten, maar beschadigt op termijn vaten en organen: linkerventrikelhypertrofie, hartfalen, CVA, nierschade en retinopathie. Behandeling: leefstijl (zout, gewicht, beweging, alcohol) en medicatie (o.a. diuretica, ACE-remmers/ARB's, calciumantagonisten).</p>","image_url":"","wiki_title":"Hypertension","match":"hypertensie|hoge bloeddruk|arteriële hypertensie","option_only":true},"acute cholecystitis":{"title":"Acute cholecystitis","short":"Acute cholecystitis is een ontsteking van de galblaas, meestal doordat een galsteen de ductus cysticus afsluit; pijn rechtsboven, koorts en een positief teken van Murphy.","definition":"<p>Bij een <strong>acute cholecystitis</strong> blokkeert meestal een galsteen de <em>ductus cysticus</em>. De galblaas zwelt, de wand raakt geïrriteerd en ontstoken, en secundair kan een bacteriële infectie ontstaan.</p><p>Klachten: aanhoudende pijn rechts in de bovenbuik (langer dan een galsteenkoliek), koorts en een positief <em>teken van Murphy</em> (pijn en stokkende inademing bij palpatie onder de ribboog). De echo toont galstenen, een verdikte galblaaswand en vocht rond de galblaas. Behandeling: antibiotica en (vroege) cholecystectomie.</p>","image_url":"","wiki_title":"Cholecystitis","match":"acute cholecystitis|cholecystitis|galblaasontsteking","option_only":true},"acuut ernstig bloedverlies":{"title":"Acuut ernstig bloedverlies","short":"Bij acuut ernstig bloedverlies daalt het circulerend volume; het lichaam reageert met tachycardie en vaatvernauwing, en bij groot verlies ontstaat hypovolemische shock.","definition":"<p>Bij <strong>acuut bloedverlies</strong> verliest het lichaam in korte tijd veel bloedvolume. De baroreceptorreflex activeert het sympathische zenuwstelsel: tachycardie, vasoconstrictie (bleke, koude huid) en verhoogde contractiliteit; het RAAS en ADH houden zout en water vast.</p><p>In de eerste uren is het <em>hemoglobine nog normaal</em>, omdat bloed met cellen én plasma tegelijk verloren gaat; pas na verdunning met weefselvocht (en infusie) daalt het Hb. Bij groot verlies (&gt;30–40%) ontstaat hypovolemische shock met hypotensie en orgaanhypoperfusie.</p>","image_url":"","wiki_title":"","match":"acuut ernstig bloedverlies|acuut bloedverlies|hemorragische shock","option_only":true},"koorts":{"title":"Koorts","short":"Koorts is een verhoogde lichaamstemperatuur (≥38,0 °C) doordat de hypothalamus het setpoint hoger instelt, meestal als reactie op infectie.","definition":"<p>Bij <strong>koorts</strong> wordt het temperatuursetpoint in de hypothalamus verhoogd. Pyrogenen zoals bacteriële producten en cytokines (IL-1, IL-6, TNF) stimuleren daar de productie van prostaglandine E<sub>2</sub>.</p><p>Het lichaam ervaart de normale temperatuur dan als te koud: vasoconstrictie en rillingen verhogen de temperatuur. Als het setpoint weer daalt, volgen zweten en vasodilatatie. Koortsremmers (paracetamol, NSAID's) remmen de prostaglandinesynthese. Hyperthermie (bijv. hitteberoerte) is iets anders: daar is het setpoint níet verhoogd.</p>","image_url":"","wiki_title":"Fever","match":"koorts|febris|pyrexie|hoge koorts","option_only":true},"maag":{"title":"Maag","short":"De maag slaat voedsel tijdelijk op, mengt het met maagzuur en pepsine en geeft het geleidelijk af aan het duodenum.","definition":"<p>De <strong>maag</strong> bestaat uit cardia, fundus, corpus, antrum en pylorus. Het slijmvlies bevat klieren met <em>pariëtale cellen</em> (zoutzuur en intrinsieke factor), <em>hoofdcellen</em> (pepsinogeen), slijmcellen en endocriene cellen (o.a. G-cellen met gastrine in het antrum).</p><p>De maag doodt micro-organismen, start de eiwitvertering en mengt voedsel tot chymus. Intrinsieke factor is nodig voor opname van vitamine B12 in het terminale ileum.</p>","image_url":"","wiki_title":"Stomach","match":"maag|gaster|ventriculus","option_only":true},"hyposfagma":{"title":"Hyposfagma","short":"Een hyposfagma is een onschuldige bloeding onder het bindvlies van het oog: een scherp begrensde felrode vlek, zonder pijn of visusklachten.","definition":"<p>Bij een <strong>hyposfagma</strong> knapt een bloedvaatje onder de conjunctiva. Het oog krijgt een scherp begrensde, felrode vlek op het oogwit, zonder pijn, afscheiding of slechter zien.</p><p>Oorzaken: hoesten, persen, niezen, wrijven, hypertensie of antistolling; vaak is er geen oorzaak. Het verdwijnt vanzelf binnen 1–3 weken. Alleen bij trauma, herhaling of bloedingsneiging is verder onderzoek nodig.</p>","image_url":"","wiki_title":"Subconjunctival bleeding","match":"hyposfagma|subconjunctivale bloeding","option_only":true},"duodenum":{"title":"Duodenum (twaalfvingerige darm)","short":"Het duodenum is het eerste, C-vormige deel van de dunne darm; hier komen gal en pancreassap bij de voedselbrij.","definition":"<p>Het <strong>duodenum</strong> loopt van de pylorus in een C-bocht om de pancreaskop heen en gaat bij de flexura duodenojejunalis over in het jejunum. Het ligt grotendeels retroperitoneaal. In de pars descendens mondt via de papil van Vater de ductus choledochus samen met de ductus pancreaticus uit. Klieren van Brunner in de submucosa maken bicarbonaatrijk slijm dat het zure chymus neutraliseert; endocriene cellen maken o.a. secretine en cholecystokinine.</p>","image_url":"","wiki_title":"Duodenum","match":"duodenum|twaalfvingerige darm","option_only":true},"colon":{"title":"Colon (dikke darm)","short":"Het colon is de dikke darm van caecum tot rectum; het resorbeert water en zouten en dikt de ontlasting in.","definition":"<p>Het <strong>colon</strong> bestaat uit caecum, colon ascendens, transversum, descendens en sigmoideum, gevolgd door het rectum. Kenmerkend zijn taeniae coli, haustra en appendices epiploicae. Het slijmvlies heeft geen villi maar wel diepe crypten met veel slijmbekercellen. Het colon resorbeert water en elektrolyten, en de darmflora fermenteert vezels tot korteketenvetzuren.</p>","image_url":"","wiki_title":"Large intestine","match":"colon|dikke darm|dikkedarm","option_only":true},"ileum":{"title":"Ileum","short":"Het ileum is het laatste deel van de dunne darm; het terminale ileum neemt vitamine B12 en galzouten op.","definition":"<p>Het <strong>ileum</strong> ligt vooral rechtsonder in de buik en eindigt bij de ileocaecaalklep. Het heeft lagere kringplooien dan het jejunum en veel lymfatisch weefsel in de vorm van Peyerse platen. Het <em>terminale ileum</em> resorbeert vitamine B12 (gebonden aan intrinsieke factor) en galzouten, die via de enterohepatische kringloop terug naar de lever gaan.</p>","image_url":"","wiki_title":"Ileum","match":"ileum","option_only":true},"psychose":{"title":"Psychose","short":"Een psychose is een toestand waarin het contact met de werkelijkheid verstoord is, met wanen en/of hallucinaties.","definition":"<p>Bij een <strong>psychose</strong> komen wanen, hallucinaties en/of ernstig verward denken en gedrag voor. Psychosen komen voor bij schizofrenie, bipolaire stoornis, ernstige depressie, delier, middelengebruik en lichamelijke ziekten. De positieve symptomen hangen samen met een overmaat aan dopamine in de mesolimbische baan; behandeling met antipsychotica.</p>","image_url":"","wiki_title":"Psychosis","match":"psychose|psychotische stoornis","option_only":true},"antibiotica":{"title":"Antibiotica","short":"Antibiotica zijn middelen die bacteriën doden of hun groei remmen; ze werken niet tegen virussen.","definition":"<p><strong>Antibiotica</strong> grijpen aan op structuren die bacteriën wel en menselijke cellen niet (of anders) hebben: de celwand (bètalactams, vancomycine), het ribosoom (o.a. macroliden, tetracyclines, aminoglycosiden), DNA-synthese (chinolonen, metronidazol) of foliumzuursynthese (trimethoprim, sulfonamiden). Bacteriostatisch betekent groeiremmend, bactericide dodend. Onnodig gebruik bevordert resistentie.</p>","image_url":"","wiki_title":"Antibiotic","match":"antibiotica|antibioticum","option_only":true},"hyperkaliëmie":{"title":"Hyperkaliëmie","short":"Hyperkaliëmie is een te hoog kalium in het bloed; gevaarlijk door het risico op hartritmestoornissen.","definition":"<p><strong>Hyperkaliëmie</strong> ontstaat door verminderde uitscheiding (nierfalen, ACE-remmers, ARB's, kaliumsparende diuretica, hypoaldosteronisme), verschuiving uit de cel (acidose, insulinetekort, celafbraak) of overmatige inname. Op het ECG ziet men spitse T-toppen, verbrede QRS-complexen en uiteindelijk ventrikelfibrilleren. Acute behandeling: calciumgluconaat (membraanstabilisatie), insuline met glucose en salbutamol, en kalium verwijderen.</p>","image_url":"","wiki_title":"Hyperkalemia","match":"hyperkaliëmie|hyperkaliemie","option_only":true},"metabole acidose":{"title":"Metabole acidose","short":"Bij een metabole acidose is het bicarbonaat verlaagd en daalt de pH, door ophoping van zuren of verlies van bicarbonaat.","definition":"<p>Een <strong>metabole acidose</strong> wordt ingedeeld met de aniongap. Een <em>verhoogde</em> aniongap past bij ophoping van zuren: lactaat, ketonen (diabetische ketoacidose), nierfalen of intoxicaties (methanol, ethyleenglycol, salicylaten). Een <em>normale</em> aniongap past bij verlies van bicarbonaat via diarree of een renale tubulaire acidose. De ademhaling compenseert met diepe, snelle ademhaling (Kussmaul).</p>","image_url":"","wiki_title":"Metabolic acidosis","match":"metabole acidose","option_only":true},"hyperglycemie":{"title":"Hyperglykemie","short":"Hyperglykemie is een te hoge bloedglucose, zoals bij diabetes mellitus.","definition":"<p>Bij <strong>hyperglykemie</strong> komt glucose boven de nierdrempel (ongeveer 10 mmol/L) in de urine, wat osmotische diurese, dorst en polyurie geeft. Ernstige ontregeling kan leiden tot diabetische ketoacidose (vooral type 1) of een hyperosmolair hyperglykemisch syndroom (vooral type 2). Ook stress, infectie en corticosteroïden kunnen de glucose verhogen.</p>","image_url":"","wiki_title":"Hyperglycemia","match":"hyperglycemie|hyperglykemie","option_only":true},"hyperthyreoïdie":{"title":"Hyperthyreoïdie","short":"Hyperthyreoïdie is een te snelle schildklierwerking, met hartkloppingen, gewichtsverlies, warmte-intolerantie en onrust.","definition":"<p><strong>Hyperthyreoïdie</strong> wordt o.a. veroorzaakt door de ziekte van Graves, een toxisch multinodulair struma, een toxisch adenoom of een (tijdelijke) thyreoïditis. Klachten: hartkloppingen of boezemfibrilleren, gewichtsverlies ondanks goede eetlust, zweten, tremor, onrust, slecht slapen en diarree. Diagnose: laag TSH met verhoogd vrij T4.</p>","image_url":"","wiki_title":"Hyperthyroidism","match":"hyperthyreoïdie|hyperthyreoidie|hyperthyreoïdie|overactieve schildklier","option_only":true},"metabool syndroom":{"title":"Metabool syndroom","short":"Het metabool syndroom is een combinatie van buikvetzucht, hoge bloeddruk, verhoogde glucose en een ongunstig lipidenprofiel, met een verhoogd risico op hart- en vaatziekten.","definition":"<p>Er is sprake van een <strong>metabool syndroom</strong> als minstens drie van de volgende kenmerken aanwezig zijn: een vergrote middelomtrek, verhoogde triglyceriden, verlaagd HDL-cholesterol, verhoogde bloeddruk en verhoogde nuchtere glucose. Insulineresistentie speelt een centrale rol. Het verhoogt het risico op diabetes type 2, hart- en vaatziekten en leververvetting.</p>","image_url":"","wiki_title":"Metabolic syndrome","match":"metabool syndroom|metabolisch syndroom","option_only":true},"colitis ulcerosa":{"title":"Colitis ulcerosa","short":"Colitis ulcerosa is een chronische ontstekingsziekte van het slijmvlies van de dikke darm, die altijd in het rectum begint en zich doorlopend naar proximaal uitbreidt.","definition":"<p>Bij <strong>colitis ulcerosa</strong> is alleen de mucosa ontstoken, zonder ‘skip lesions’. Klachten: bloederige diarree met slijm, aandrang en buikkrampen. Extra-intestinale verschijnselen zijn o.a. artritis, uveïtis, erythema nodosum en primaire scleroserende cholangitis. Langdurige ziekte verhoogt het risico op coloncarcinoom. Roken lijkt (in tegenstelling tot bij Crohn) beschermend.</p>","image_url":"","wiki_title":"Ulcerative colitis","match":"colitis ulcerosa|ulceratieve colitis","option_only":true},"coeliakie":{"title":"Coeliakie","short":"Coeliakie is een auto-immuunziekte waarbij gluten een ontsteking van de dunne darm met vlokatrofie veroorzaken.","definition":"<p>Bij <strong>coeliakie</strong> (geassocieerd met HLA-DQ2/DQ8) wordt gliadine door weefseltransglutaminase gemodificeerd en daarna door T-cellen herkend, wat leidt tot vlokatrofie en crypthyperplasie. Klachten: diarree, buikpijn, gewichtsverlies, groeiachterstand, ijzergebrek en vermoeidheid, maar ook atypische presentaties. Diagnose met anti-tTG-antistoffen en een duodenumbiopt; behandeling is een levenslang glutenvrij dieet.</p>","image_url":"","wiki_title":"Coeliac disease","match":"coeliakie|glutenintolerantie|glutenenteropathie","option_only":true},"maagperforatie":{"title":"Maagperforatie","short":"Bij een maagperforatie ontstaat een gat in de maagwand, meestal door een ulcus, waardoor maaginhoud in de buikholte lekt.","definition":"<p>Een <strong>perforatie</strong> van maag of duodenum geeft plotselinge, hevige bovenbuikpijn die zich snel over de hele buik uitbreidt, met een plankharde buik (chemische peritonitis). Op een staande X-thorax of CT is vrij lucht onder het diafragma te zien. Risicofactoren zijn NSAID-gebruik, <em>H. pylori</em> en roken. Behandeling is meestal chirurgisch sluiten.</p>","image_url":"","wiki_title":"Gastrointestinal perforation","match":"maagperforatie|perforatie van de maag|ulcusperforatie","option_only":true},"refluxklachten":{"title":"Gastro-oesofageale reflux","short":"Bij refluxklachten stroomt maaginhoud terug in de slokdarm, met zuurbranden en oprispingen.","definition":"<p><strong>Gastro-oesofageale refluxziekte</strong> ontstaat bij een tekortschietende onderste slokdarmsfincter, een hiatus hernia of verhoogde druk in de buik (overgewicht, zwangerschap). Klachten zijn zuurbranden achter het borstbeen en zure oprispingen, soms hoesten of heesheid. Complicaties: oesofagitis, stenose en Barrett-slokdarm. Behandeling met leefstijladviezen en protonpompremmers.</p>","image_url":"","wiki_title":"Gastroesophageal reflux disease","match":"refluxklachten|reflux|gastro-oesofageale reflux|zuurbranden|refluxziekte","option_only":true},"acuut glaucoom":{"title":"Acuut (gesloten-kamerhoek) glaucoom","short":"Bij acuut glaucoom raakt de kamerhoek plotseling afgesloten, waardoor de oogdruk sterk stijgt; een spoedgeval.","definition":"<p>Bij een <strong>acuut gesloten-kamerhoekglaucoom</strong> blokkeert de iris de afvloed van kamerwater, vaak bij verziende ouderen met een ondiepe voorste oogkamer, uitgelokt door pupilverwijding (schemer, medicatie). Klachten: hevige oogpijn en hoofdpijn, misselijkheid en braken, wazig zien met halo's, een rood oog, een matte cornea en een middelwijde, lichtstijve pupil. Behandeling: oogdrukverlagende medicatie en laseriridotomie.</p>","image_url":"","wiki_title":"Angle-closure glaucoma","match":"acuut glaucoom|acuut gesloten-kamerhoekglaucoom|glaucoomaanval","option_only":true},"refractieafwijking":{"title":"Refractieafwijking","short":"Een refractieafwijking betekent dat het oog licht niet scherp op het netvlies focust: bijziendheid, verziendheid of astigmatisme.","definition":"<p>Bij <strong>myopie</strong> (bijziendheid) valt het brandpunt vóór de retina, bij <strong>hypermetropie</strong> (verziendheid) erachter, en bij <strong>astigmatisme</strong> is de breking niet in alle richtingen gelijk. Presbyopie is leeftijdsgebonden verlies van accommodatie. Verbetering van het zicht met een stenopeïsche opening wijst op een refractieprobleem. Correctie met bril, lenzen of refractiechirurgie.</p>","image_url":"","wiki_title":"Refractive error","match":"refractieafwijking|refractiefout","option_only":true},"trombolyse":{"title":"Trombolyse","short":"Trombolyse is het oplossen van een stolsel met een middel dat plasminogeen activeert, zoals alteplase.","definition":"<p>Bij <strong>trombolyse</strong> wordt een plasminogeenactivator (bijv. alteplase, tenecteplase) toegediend, waardoor plasmine ontstaat dat fibrine afbreekt. Het wordt gebruikt bij een acuut herseninfarct (binnen 4,5 uur), soms bij een massale longembolie en (als PCI niet snel kan) bij een STEMI. Het belangrijkste risico is een bloeding, waaronder een hersenbloeding.</p>","image_url":"","wiki_title":"Thrombolysis","match":"trombolyse|trombolytica|alteplase","option_only":true},"antipsychotica":{"title":"Antipsychotica","short":"Antipsychotica blokkeren dopamine-D2-receptoren en worden gebruikt bij psychosen, manie en ernstige onrust.","definition":"<p>Klassieke (eerste generatie) <strong>antipsychotica</strong> zoals haloperidol geven vaak extrapiramidale bijwerkingen. Atypische (tweede generatie) middelen zoals olanzapine, risperidon, quetiapine en clozapine blokkeren ook serotonine-5-HT2A-receptoren en geven minder extrapiramidale, maar vaker metabole bijwerkingen (gewichtstoename, diabetes). Blokkade in de tubero-infundibulaire baan geeft hyperprolactinemie.</p>","image_url":"","wiki_title":"Antipsychotic","match":"antipsychotica|antipsychoticum|neuroleptica","option_only":true},"topiramaat":{"title":"Topiramaat","short":"Topiramaat is een anti-epilepticum dat ook wordt gebruikt als profylaxe bij migraine.","definition":"<p><strong>Topiramaat</strong> heeft meerdere werkingsmechanismen: blokkade van natriumkanalen, versterking van GABA, remming van glutamaatreceptoren en zwakke remming van koolzuuranhydrase. Bijwerkingen zijn woordvindproblemen en cognitieve vertraging, tintelingen, gewichtsverlies, nierstenen en (zeldzaam) acuut glaucoom.</p>","image_url":"","wiki_title":"Topiramate","match":"topiramaat|topiramate","option_only":true},"naltrexon":{"title":"Naltrexon","short":"Naltrexon is een opioïdreceptorantagonist die wordt gebruikt om terugval bij alcoholverslaving te verminderen.","definition":"<p><strong>Naltrexon</strong> blokkeert µ-opioïdreceptoren en vermindert zo het belonende effect van alcohol en opioïden. Het wordt gebruikt bij alcoholafhankelijkheid (naast psychosociale behandeling) en soms bij opioïdafhankelijkheid na detoxificatie. Bij nog lopend opioïdgebruik lokt het acute onttrekkingsverschijnselen uit.</p>","image_url":"","wiki_title":"Naltrexone","match":"naltrexon|naltrexone","option_only":true},"oxazepam":{"title":"Oxazepam","short":"Oxazepam is een kortwerkend benzodiazepine dat angst vermindert en sederend werkt.","definition":"<p><strong>Benzodiazepinen</strong> versterken het effect van GABA op de GABA-A-receptor (vaker openen van het chloridekanaal). Oxazepam heeft geen actieve metabolieten en wordt via glucuronidering geklaard, waardoor het relatief geschikt is bij ouderen en leverfunctiestoornissen. Bijwerkingen: sufheid, vallen, geheugenstoornissen en afhankelijkheid bij langdurig gebruik. Antidotum: flumazenil.</p>","image_url":"","wiki_title":"Oxazepam","match":"oxazepam|benzodiazepine|benzodiazepinen","option_only":true},"antihypertensiva":{"title":"Antihypertensiva","short":"Antihypertensiva zijn geneesmiddelen die de bloeddruk verlagen.","definition":"<p>Veelgebruikte <strong>antihypertensiva</strong> zijn thiazidediuretica, ACE-remmers en angiotensinereceptorblokkers, calciumantagonisten en bètablokkers. Daarnaast bestaan o.a. aldosteronantagonisten, alfablokkers en centraal werkende middelen. De keuze hangt af van comorbiditeit, leeftijd, afkomst en bijwerkingen; vaak is een combinatie nodig.</p>","image_url":"","wiki_title":"Antihypertensive drug","match":"antihypertensiva|antihypertensivum|bloeddrukverlagers","option_only":true},"icterus":{"title":"Icterus (geelzucht)","short":"Icterus is gele verkleuring van huid, sclerae en slijmvliezen door een verhoogd bilirubine.","definition":"<p><strong>Icterus</strong> wordt meestal zichtbaar bij een bilirubine boven ongeveer 40–50 µmol/L. Men onderscheidt prehepatisch (hemolyse, vooral ongeconjugeerd bilirubine), hepatisch (leverziekte) en posthepatisch (galwegobstructie, met donkere urine en ontkleurde ontlasting). Bij pasgeborenen is lichte icterus in de eerste dagen fysiologisch.</p>","image_url":"","wiki_title":"Jaundice","match":"icterus|geelzucht","option_only":true},"diverticulitis":{"title":"Diverticulitis","short":"Diverticulitis is een ontsteking van een of meer divertikels (uitstulpingen) van de dikke darm.","definition":"<p>Bij <b>diverticulitis</b> raakt een divertikel ontstoken, vermoedelijk door obstructie en microperforatie. Divertikels ontstaan vooral bij ouderen en bij vezelarme voeding. De ernst wordt ingedeeld volgens Hinchey (van lokale ontsteking tot abces en perforatie met peritonitis). Diagnose met echo of CT; ongecompliceerde gevallen worden meestal conservatief behandeld.</p>","image_url":"","wiki_title":"Diverticulitis","match":"diverticulitis","option_only":true},"corticosteroïden":{"title":"Corticosteroïden","short":"Corticosteroïden zijn van cortisol afgeleide middelen met sterke ontstekingsremmende en immunosuppressieve werking.","definition":"<p>Glucocorticoïden binden aan een intracellulaire receptor en remmen de transcriptie van ontstekingsgenen (cytokines, COX-2) en de vorming van ontstekingsmediatoren. Ze worden lokaal (huid, inhalatie, injectie) en systemisch gebruikt. Bij langdurig systemisch gebruik: osteoporose, hyperglykemie, gewichtstoename, huidatrofie, infecties, spierzwakte, cataract en remming van de eigen bijnier (niet abrupt stoppen).</p>","image_url":"","wiki_title":"Corticosteroid","match":"corticosteroïden|corticosteroiden|glucocorticoïden|corticosteroïd","option_only":true},"pancreatitis":{"title":"Pancreatitis","short":"Pancreatitis is een ontsteking van de pancreas, acuut meestal door galstenen of alcohol.","definition":"<p><strong>Acute pancreatitis</strong> geeft hevige, gordelvormige bovenbuikpijn uitstralend naar de rug, met misselijkheid en braken; het lipase is verhoogd. Andere oorzaken zijn hypertriglyceridemie, hypercalciëmie, medicatie en ERCP. Ernstige vormen geven necrose, SIRS en orgaanfalen. Chronische pancreatitis geeft pijn, exocriene en endocriene insufficiëntie.</p>","image_url":"","wiki_title":"Pancreatitis","match":"pancreatitis|alvleesklierontsteking|acute pancreatitis","option_only":true},"melaena":{"title":"Melaena","short":"Melaena is zwarte, teerachtige, stinkende ontlasting door een bloeding hoog in het maag-darmkanaal.","definition":"<p><strong>Melaena</strong> ontstaat als bloed uit slokdarm, maag of duodenum door maagzuur en bacteriën wordt omgezet. Belangrijke oorzaken zijn een ulcus pepticum en varices. Het ureum kan verhoogd zijn door eiwitresorptie. IJzerpreparaten en bismut kleuren de ontlasting ook zwart, maar niet teerachtig.</p>","image_url":"","wiki_title":"Melena","match":"melaena|melena|teerontlasting","option_only":true},"haematemesis":{"title":"Haematemesis","short":"Haematemesis is het braken van bloed, vers rood of als ‘koffiedik’, door een bloeding in slokdarm, maag of duodenum.","definition":"<p>Oorzaken van <strong>haematemesis</strong> zijn o.a. een ulcus pepticum, oesofagusvarices (bij portale hypertensie), een Mallory-Weiss-scheur na heftig braken, oesofagitis en tumoren. Koffiedikbraaksel wijst op bloed dat al met maagzuur in contact is geweest. Beoordeling van de circulatie en een spoedgastroscopie zijn nodig.</p>","image_url":"","wiki_title":"Hematemesis","match":"haematemesis|hematemesis|bloedbraken","option_only":true},"diabetische retinopathie":{"title":"Diabetische retinopathie","short":"Diabetische retinopathie is schade aan de netvliesvaatjes door langdurig hoge bloedglucose.","definition":"<p>Bij <strong>diabetische retinopathie</strong> ontstaan eerst microaneurysmata, puntbloedingen en harde exsudaten (non-proliferatief). Bij ernstige ischemie groeien nieuwe, kwetsbare vaten (proliferatief), met risico op glasvochtbloedingen en tractieablatio. Maculaoedeem kan in elk stadium het zicht bedreigen. Behandeling met laser en anti-VEGF-injecties; screening voorkomt blindheid.</p>","image_url":"","wiki_title":"Diabetic retinopathy","match":"diabetische retinopathie","option_only":true},"maculadegeneratie":{"title":"Leeftijdsgebonden maculadegeneratie","short":"Bij maculadegeneratie raakt de gele vlek (het centrum van het netvlies) beschadigd, met verlies van het centrale zien.","definition":"<p>Bij <strong>LMD</strong> is er een droge vorm (drusen en atrofie) en een natte vorm (nieuwvorming van lekkende vaatjes onder het netvlies). Klachten zijn vervormd zien (rechte lijnen lijken krom), een vlek in het centrum en moeite met lezen en gezichten herkennen; het perifere zien blijft bewaard. Risicofactoren: leeftijd, roken en erfelijkheid. De natte vorm wordt met anti-VEGF-injecties behandeld.</p>","image_url":"","wiki_title":"Macular degeneration","match":"maculadegeneratie|leeftijdsgebonden maculadegeneratie|lmd|amd","option_only":true},"nsaid’s":{"title":"NSAID's","short":"NSAID's remmen cyclo-oxygenase en daarmee de vorming van prostaglandinen; ze werken pijnstillend, koortsverlagend en ontstekingsremmend.","definition":"<p><strong>NSAID's</strong> (zoals ibuprofen, naproxen, diclofenac) remmen COX-1 en COX-2. Door remming van beschermende prostaglandinen kunnen ze maagulcera en bloedingen geven, vooral bij ouderen; ook kunnen ze de nierfunctie verslechteren, de bloeddruk verhogen, hartfalen verergeren en het risico op hart- en vaatziekten iets verhogen. Selectieve COX-2-remmers geven minder maagschade.</p>","image_url":"","wiki_title":"Nonsteroidal anti-inflammatory drug","match":"nsaid’s","option_only":true},"appendicitis acuta":{"title":"Appendicitis","short":"Appendicitis is een ontsteking van de appendix, met buikpijn die vaak rond de navel begint en naar rechtsonder trekt.","definition":"<p>Bij <strong>appendicitis</strong> raakt het lumen van de appendix afgesloten (bijv. door een fecoliet of lymfoïde hyperplasie), waarna ontsteking en infectie volgen. Klachten: pijn eerst rond de navel, later rechtsonder (McBurney), misselijkheid, koorts en lokale peritoneale prikkeling. Zonder behandeling kan perforatie optreden. Diagnose met echo en/of CT; behandeling meestal appendectomie.</p>","image_url":"","wiki_title":"Appendicitis","match":"appendicitis acuta","option_only":true},"hoge koorts":{"title":"Koorts","short":"Koorts is een verhoogde lichaamstemperatuur (≥38,0 °C) doordat de hypothalamus het setpoint hoger instelt, meestal als reactie op infectie.","definition":"<p>Bij <strong>koorts</strong> wordt het temperatuursetpoint in de hypothalamus verhoogd. Pyrogenen zoals bacteriële producten en cytokines (IL-1, IL-6, TNF) stimuleren daar de productie van prostaglandine E<sub>2</sub>.</p><p>Het lichaam ervaart de normale temperatuur dan als te koud: vasoconstrictie en rillingen verhogen de temperatuur. Als het setpoint weer daalt, volgen zweten en vasodilatatie. Koortsremmers (paracetamol, NSAID's) remmen de prostaglandinesynthese. Hyperthermie (bijv. hitteberoerte) is iets anders: daar is het setpoint níet verhoogd.</p>","image_url":"","wiki_title":"Fever","match":"hoge koorts","option_only":true},"episcleritis":{"title":"Episcleritis","short":"Episcleritis is een milde, meestal onschuldige ontsteking van de laag tussen bindvlies en sclera, met een lokaal rood oog.","definition":"<p>Bij <strong>episcleritis</strong> is een sectorvormig deel van het oog rood, met weinig pijn en normaal zicht. Het verdwijnt meestal vanzelf. Het onderscheid met scleritis (hevige, borende pijn; vaak bij systemische ziekten zoals reumatoïde artritis) is belangrijk.</p>","image_url":"","wiki_title":"Episcleritis","match":"episcleritis","option_only":true},"nucleair cataract":{"title":"Nucleaire cataract","short":"Bij nucleaire cataract vertroebelt en verkleurt de kern van de ooglens, vaak met een toenemende bijziendheid.","definition":"<p><strong>Nucleaire cataract</strong> is de meest voorkomende ouderdomsstaar. De lenskern wordt geler en harder; door de toegenomen brekingskracht kunnen mensen soms weer zonder leesbril lezen (‘second sight’). Kleuren worden minder helder waargenomen. Behandeling is een staaroperatie.</p>","image_url":"","wiki_title":"Cataract","match":"nucleair cataract|nucleaire cataract|kernstaar","option_only":true},"uveitis anterior":{"title":"Uveïtis anterior","short":"Uveïtis anterior is een ontsteking van iris en corpus ciliare, met een pijnlijk rood oog, lichtschuwheid en wazig zien.","definition":"<p>Bij <strong>uveïtis anterior</strong> zijn er cellen en flare in de voorste oogkamer, ciliaire injectie en soms een nauwe of onregelmatige pupil (synechieën). Het kan samenhangen met HLA-B27-gerelateerde ziekten, sarcoïdose, JIA of infecties. Behandeling met corticosteroïd- en pupilverwijdende druppels.</p>","image_url":"","wiki_title":"Uveitis","match":"uveitis anterior|uveïtis anterior|iridocyclitis|iritis","option_only":true},"ziekte van crohn":{"title":"Ziekte van Crohn","short":"De ziekte van Crohn is een chronische ontstekingsziekte die het hele maag-darmkanaal kan treffen, met transmurale ontsteking en ‘skip lesions’.","definition":"<p>De <strong>ziekte van Crohn</strong> zit vaak in het terminale ileum. Klachten: buikpijn, (niet altijd bloederige) diarree, gewichtsverlies en perianale fistels. Complicaties zijn stenosen, fistels en abcessen. Histologisch zijn er soms niet-verkazende granulomen. Roken verergert de ziekte.</p>","image_url":"","wiki_title":"Crohn's disease","match":"ziekte van crohn|crohn|m. crohn","option_only":true},"cholelithiasis":{"title":"Cholelithiasis (galstenen)","short":"Cholelithiasis betekent galstenen in de galblaas; veel mensen hebben geen klachten, anderen krijgen koliekpijn of complicaties.","definition":"<p>De meeste <strong>galstenen</strong> zijn cholesterolstenen (risicofactoren: vrouw, overgewicht, snel afvallen, zwangerschap, leeftijd); pigmentstenen ontstaan bij hemolyse. Een galsteenkoliek geeft heftige pijn rechtsboven of in het epigastrium. Complicaties zijn cholecystitis, choledocholithiasis, cholangitis en pancreatitis.</p>","image_url":"","wiki_title":"Gallstone","match":"cholelithiasis|galstenen|galsteenlijden","option_only":true},"keratitis":{"title":"Keratitis","short":"Keratitis is een ontsteking van het hoornvlies, met pijn, lichtschuwheid, tranen en soms visusdaling.","definition":"<p><strong>Keratitis</strong> kan infectieus zijn (bacterieel, vooral bij contactlensdragers; herpes simplex met dendritische afwijkingen; acanthamoeba; schimmels) of niet-infectieus (droge ogen, lagophthalmus, UV). Bacteriële keratitis is een spoedgeval wegens risico op perforatie en littekens.</p>","image_url":"","wiki_title":"Keratitis","match":"keratitis|hoornvliesontsteking","option_only":true},"neuromyelitis optica":{"title":"Neuromyelitis optica","short":"Neuromyelitis optica is een auto-immuunziekte met ernstige ontsteking van oogzenuwen en ruggenmerg, door antistoffen tegen aquaporine-4.","definition":"<p>Bij <strong>NMO</strong> ontstaan ernstige opticus-neuritiden en een uitgebreide myelitis over drie of meer segmenten, soms een area postrema-syndroom (onbedwingbaar braken en hikken). Het onderscheid met MS is belangrijk, omdat sommige MS-middelen NMO verergeren.</p>","image_url":"","wiki_title":"Neuromyelitis optica","match":"neuromyelitis optica|nmo|devic","option_only":true},"uveïtis anterior":{"title":"Uveïtis anterior","short":"Uveïtis anterior is een ontsteking van iris en corpus ciliare, met een pijnlijk rood oog, lichtschuwheid en wazig zien.","definition":"<p>Bij <strong>uveïtis anterior</strong> zijn er cellen en flare in de voorste oogkamer, ciliaire injectie en soms een nauwe of onregelmatige pupil (synechieën). Het kan samenhangen met HLA-B27-gerelateerde ziekten, sarcoïdose, JIA of infecties. Behandeling met corticosteroïd- en pupilverwijdende druppels.</p>","image_url":"","wiki_title":"Uveitis","match":"uveïtis anterior","option_only":true},"bacteriële conjunctivitis":{"title":"Conjunctivitis","short":"Conjunctivitis is een ontsteking van het bindvlies, met een rood oog, tranen of afscheiding en een branderig gevoel, zonder visusdaling.","definition":"<p><strong>Conjunctivitis</strong> kan viraal (vaak adenovirus, waterige afscheiding), bacterieel (purulente afscheiding) of allergisch (jeuk, beide ogen, seizoensgebonden) zijn. Het zicht is normaal en er is meestal geen echte pijn of lichtschuwheid; die passen eerder bij keratitis, uveïtis of glaucoom. Bij pasgeborenen moet aan chlamydia of gonokokken worden gedacht.</p>","image_url":"","wiki_title":"Conjunctivitis","match":"bacteriële conjunctivitis","option_only":true},"een corticosteroïd":{"title":"Corticosteroïden","short":"Corticosteroïden zijn van cortisol afgeleide middelen met sterke ontstekingsremmende en immunosuppressieve werking.","definition":"<p>Glucocorticoïden binden aan een intracellulaire receptor en remmen de transcriptie van ontstekingsgenen (cytokines, COX-2) en de vorming van ontstekingsmediatoren. Ze worden lokaal (huid, inhalatie, injectie) en systemisch gebruikt. Bij langdurig systemisch gebruik: osteoporose, hyperglykemie, gewichtstoename, huidatrofie, infecties, spierzwakte, cataract en remming van de eigen bijnier (niet abrupt stoppen).</p>","image_url":"","wiki_title":"Corticosteroid","match":"een corticosteroïd","option_only":true},"refractie afwijking":{"title":"Refractieafwijking","short":"Een refractieafwijking betekent dat het oog licht niet scherp op het netvlies focust: bijziendheid, verziendheid of astigmatisme.","definition":"<p>Bij <strong>myopie</strong> (bijziendheid) valt het brandpunt vóór de retina, bij <strong>hypermetropie</strong> (verziendheid) erachter, en bij <strong>astigmatisme</strong> is de breking niet in alle richtingen gelijk. Presbyopie is leeftijdsgebonden verlies van accommodatie. Verbetering van het zicht met een stenopeïsche opening wijst op een refractieprobleem. Correctie met bril, lenzen of refractiechirurgie.</p>","image_url":"","wiki_title":"Refractive error","match":"refractie afwijking","option_only":true},"diverticultis":{"title":"Diverticulitis","short":"Diverticulitis is een ontsteking van een of meer divertikels (uitstulpingen) van de dikke darm.","definition":"<p>Bij <b>diverticulitis</b> raakt een divertikel ontstoken, vermoedelijk door obstructie en microperforatie. Divertikels ontstaan vooral bij ouderen en bij vezelarme voeding. De ernst wordt ingedeeld volgens Hinchey (van lokale ontsteking tot abces en perforatie met peritonitis). Diagnose met echo of CT; ongecompliceerde gevallen worden meestal conservatief behandeld.</p>","image_url":"","wiki_title":"Diverticulitis","match":"diverticultis","option_only":true},"m. crohn":{"title":"Ziekte van Crohn","short":"De ziekte van Crohn is een chronische ontstekingsziekte die het hele maag-darmkanaal kan treffen, met transmurale ontsteking en ‘skip lesions’.","definition":"<p>De <strong>ziekte van Crohn</strong> zit vaak in het terminale ileum. Klachten: buikpijn, (niet altijd bloederige) diarree, gewichtsverlies en perianale fistels. Complicaties zijn stenosen, fistels en abcessen. Histologisch zijn er soms niet-verkazende granulomen. Roken verergert de ziekte.</p>","image_url":"","wiki_title":"Crohn's disease","match":"m. crohn","option_only":true},"spanningspneumothorax links":{"title":"Spanningspneumothorax","short":"Bij een spanningspneumothorax hoopt lucht zich via een ventielmechanisme op in de pleuraholte, met verschuiving van het mediastinum en circulatoire shock.","definition":"<p>Kenmerken van een <strong>spanningspneumothorax</strong>: ernstige benauwdheid, hypotensie, gestuwde halsvenen, afwezig ademgeruis en hypersonore percussie aan de aangedane kant, en een trachea die naar de andere kant wijst. Het is een klinische diagnose en vraagt om directe ontlasting met een naald of thoracostomie, gevolgd door een drain.</p>","image_url":"","wiki_title":"Tension pneumothorax","match":"spanningspneumothorax links|spanningspneumothorax","option_only":true},"antidepressiva":{"title":"Antidepressiva","short":"Antidepressiva zijn geneesmiddelen tegen depressie en angststoornissen, die vooral de serotonerge en noradrenerge overdracht beïnvloeden.","definition":"<p>Groepen zijn SSRI's (bijv. sertraline, citalopram), SNRI's (venlafaxine, duloxetine), tricyclische antidepressiva, mirtazapine en MAO-remmers. Het effect treedt na 2–6 weken op. Bij jongeren kan in het begin de suïcidaliteit toenemen; abrupt stoppen geeft onttrekkingsverschijnselen.</p>","image_url":"","wiki_title":"Antidepressant","match":"antidepressiva|antidepressivum","option_only":true},"hsv keratitis":{"title":"Herpes simplex-keratitis","short":"Herpes simplex-keratitis is een virale hoornvliesinfectie met een kenmerkende boomvormige (dendritische) afwijking bij fluoresceïnekleuring.","definition":"<p><strong>HSV-keratitis</strong> geeft een rood, pijnlijk, lichtschuw oog, vaak recidiverend. De gevoeligheid van het hoornvlies is verminderd. Behandeling met antivirale middelen; corticosteroïddruppels zonder antivirale dekking kunnen het ernstig verergeren.</p>","image_url":"","wiki_title":"Herpes simplex keratitis","match":"hsv keratitis|herpes simplex keratitis|herpeskeratitis","option_only":true},"auto immuun hemolytische anemie":{"title":"Auto-immuun hemolytische anemie","short":"Bij AIHA maakt het lichaam antistoffen tegen de eigen rode bloedcellen, die daardoor worden afgebroken; de directe antiglobulinetest (Coombs) is positief.","definition":"<p>Bij <strong>auto-immuun hemolytische anemie</strong> binden auto-antistoffen aan erytrocyten, die vervolgens vooral in de milt worden afgebroken (type II-overgevoeligheid). Bij <em>warme</em> AIHA gaat het om IgG; bij <em>koude</em> AIHA om IgM met complementactivatie.</p><p>Laboratorium: anemie met verhoogde reticulocyten, verhoogd LDH en ongeconjugeerd bilirubine, verlaagd haptoglobine, sferocyten en een positieve directe antiglobulinetest (Coombs). Oorzaken: idiopathisch, lymfoproliferatieve ziekten, SLE, infecties (Mycoplasma, EBV) of geneesmiddelen.</p>","image_url":"","wiki_title":"Autoimmune hemolytic anemia","match":"auto immuun hemolytische anemie","option_only":true},"hyperkaliumie":{"title":"Hyperkaliëmie","short":"Hyperkaliëmie is een te hoog kalium in het bloed; gevaarlijk door het risico op hartritmestoornissen.","definition":"<p><strong>Hyperkaliëmie</strong> ontstaat door verminderde uitscheiding (nierfalen, ACE-remmers, ARB's, kaliumsparende diuretica, hypoaldosteronisme), verschuiving uit de cel (acidose, insulinetekort, celafbraak) of overmatige inname. Op het ECG ziet men spitse T-toppen, verbrede QRS-complexen en uiteindelijk ventrikelfibrilleren. Acute behandeling: calciumgluconaat (membraanstabilisatie), insuline met glucose en salbutamol, en kalium verwijderen.</p>","image_url":"","wiki_title":"Hyperkalemia","match":"hyperkaliumie","option_only":true},"scleritis":{"title":"Scleritis","short":"Scleritis is een ernstige, pijnlijke ontsteking van het oogwit, vaak bij systemische auto-immuunziekten.","definition":"<p>Bij <strong>scleritis</strong> is er een diepe, borende oogpijn die ’s nachts erger is, met een paarsrode verkleuring die niet verbleekt bij druppelen met fenylefrine (anders dan episcleritis). Ze komt voor bij reumatoïde artritis en GPA en kan het oog ernstig beschadigen; systemische behandeling is nodig.</p>","image_url":"","wiki_title":"Scleritis","match":"scleritis","option_only":true},"uveitis posterior":{"title":"Uveïtis posterior","short":"Uveïtis posterior is een ontsteking van het achterste deel van het oog (choroidea en/of retina), met wazig zien en vlekken, meestal zonder pijn of rood oog.","definition":"<p>Oorzaken van <strong>uveïtis posterior</strong> zijn o.a. toxoplasmose (meest voorkomend), CMV (bij afweerstoornissen), sarcoïdose, syfilis, tuberculose en de ziekte van Behçet. Diagnose met fundoscopie; behandeling van de oorzaak, eventueel met corticosteroïden.</p>","image_url":"","wiki_title":"Uveitis","match":"uveitis posterior|uveïtis posterior|chorioretinitis","option_only":true},"allergische conjunctivitis":{"title":"Allergische conjunctivitis","short":"Allergische conjunctivitis is een allergische ontsteking van het bindvlies, met jeukende, tranende en rode ogen aan beide kanten.","definition":"<p>De <strong>allergische conjunctivitis</strong> is vaak seizoensgebonden (pollen) of het hele jaar door (huisstofmijt, huisdieren), meestal samen met allergische rhinitis. Jeuk is het belangrijkste onderscheid met infectieuze conjunctivitis. Behandeling met antihistaminica of mestcelstabiliserende oogdruppels.</p>","image_url":"","wiki_title":"Allergic conjunctivitis","match":"allergische conjunctivitis|jeukende en tranende ogen|jeuk in de ogen","option_only":true},"adenovirale conjunctivitis":{"title":"Adenovirale conjunctivitis","short":"Adenovirale conjunctivitis is een zeer besmettelijke virale bindvliesontsteking met tranen, rood oog en vaak een gezwollen preauriculaire lymfeklier.","definition":"<p>Bij <strong>adenovirale conjunctivitis</strong> begint het vaak aan één oog en volgt het andere enkele dagen later. Bij keratoconjunctivitis epidemica kunnen hoornvliesinfiltraten weken tot maanden wazig zien geven. Strikte handhygiëne is belangrijk, ook in de spreekkamer.</p>","image_url":"","wiki_title":"Adenoviral conjunctivitis","match":"adenovirale conjunctivitis|keratoconjunctivitis epidemica","option_only":true},"subconjunctivale bloeding":{"title":"Hyposfagma","short":"Een hyposfagma is een onschuldige bloeding onder het bindvlies van het oog: een scherp begrensde felrode vlek, zonder pijn of visusklachten.","definition":"<p>Bij een <strong>hyposfagma</strong> knapt een bloedvaatje onder de conjunctiva. Het oog krijgt een scherp begrensde, felrode vlek op het oogwit, zonder pijn, afscheiding of slechter zien.</p><p>Oorzaken: hoesten, persen, niezen, wrijven, hypertensie of antistolling; vaak is er geen oorzaak. Het verdwijnt vanzelf binnen 1–3 weken. Alleen bij trauma, herhaling of bloedingsneiging is verder onderzoek nodig.</p>","image_url":"","wiki_title":"Subconjunctival bleeding","match":"subconjunctivale bloeding","option_only":true},"eeg":{"title":"EEG (elektro-encefalogram)","short":"Een EEG registreert de elektrische activiteit van de hersenen via elektroden op de hoofdhuid.","definition":"<p>Een <strong>EEG</strong> wordt vooral gebruikt bij epilepsie (epileptiforme afwijkingen, type epilepsie), bij onverklaarde bewustzijnsstoornissen (non-convulsieve status, encefalopathie) en bij slaaponderzoek. Een normaal EEG tussen aanvallen sluit epilepsie niet uit.</p>","image_url":"","wiki_title":"Electroencephalography","match":"eeg|elektro-encefalogram","option_only":true},"levercirrose":{"title":"Levercirrose","short":"Bij levercirrose is het leverweefsel vervangen door bindweefsel en regeneratieknobbels, met verlies van leverfunctie en portale hypertensie.","definition":"<p>Oorzaken van <strong>cirrose</strong> zijn o.a. alcohol, NASH, chronische hepatitis B en C, auto-immuunziekten en hemochromatose. Gevolgen: ascites, varices met bloedingen, hepatische encefalopathie, icterus, stollingsstoornissen en een verhoogd risico op hepatocellulair carcinoom. Ernst wordt ingedeeld met Child-Pugh of MELD.</p>","image_url":"","wiki_title":"Cirrhosis","match":"levercirrose|cirrose|cirrhose","option_only":true},"uveitis":{"title":"Uveïtis anterior","short":"Uveïtis anterior is een ontsteking van iris en corpus ciliare, met een pijnlijk rood oog, lichtschuwheid en wazig zien.","definition":"<p>Bij <strong>uveïtis anterior</strong> zijn er cellen en flare in de voorste oogkamer, ciliaire injectie en soms een nauwe of onregelmatige pupil (synechieën). Het kan samenhangen met HLA-B27-gerelateerde ziekten, sarcoïdose, JIA of infecties. Behandeling met corticosteroïd- en pupilverwijdende druppels.</p>","image_url":"","wiki_title":"Uveitis","match":"uveitis","option_only":true},"migraine":{"title":"Migraine","short":"Aanvalsgewijze, vaak eenzijdige kloppende hoofdpijn met misselijkheid, foto- en fonofobie, soms met aura. Duurt uren tot een dag.","definition":"<p><b>Migraine</b>-aanvallen worden verergerd door inspanning; de patiënt zoekt rust in een donkere kamer. Aanvalsbehandeling met triptanen bij onvoldoende effect van NSAID's.</p>","image_url":"","wiki_title":"Migraine","match":"migraine","option_only":true},"virale hepatitis":{"title":"Virale hepatitis","short":"Leverontsteking door een hepatitisvirus (A, B, C, D of E), met sterk verhoogde transaminasen.","definition":"<p><b>Virale hepatitis</b> is een ontsteking van de lever door hepatotrope virussen. Kenmerkend zijn fors verhoogde transaminasen (ALAT vaak hoger dan ASAT); hepatitis B en C kunnen chronisch worden en tot cirrose/carcinoom leiden.</p>","image_url":"","wiki_title":"Viral hepatitis","match":"virale hepatitis","option_only":true},"trombotische trombocytopenische purpura":{"title":"Trombotische trombocytopenische purpura (TTP)","short":"Levensbedreigende microangiopathie met trombocytopenie, hemolytische anemie en neurologische verschijnselen.","definition":"<p>TTP berust op ADAMTS13-deficiëntie met microtrombi. Kenmerken zijn anemie met sterk verhoogd LDH, trombocytopenie en verwardheid; het vereist directe verwijzing en plasmaferese.</p>","image_url":"","wiki_title":"Thrombotic thrombocytopenic purpura","match":"trombotische trombocytopenische purpura","option_only":true},"papiloedeem":{"title":"Papiloedeem","short":"Zwelling van de oogzenuwkop door verhoogde intracraniële druk; zichtbaar bij fundoscopie en teken van maligne hypertensie.","definition":"<p><b>Papiloedeem</b> is zwelling van de papil (oogzenuwkop) door verhoogde hersendruk. Bij zeer hoge bloeddruk (maligne hypertensie) is het een teken van eindorgaanschade.</p>","image_url":"","wiki_title":"Papilledema","match":"papiloedeem","option_only":true},"varenicline":{"title":"Varenicline","short":"Partiële agonist van de α4β2-nicotine-acetylcholinereceptor.","definition":"<p><strong>Varenicline</strong> stimuleert de nicotinereceptor gedeeltelijk en verdringt tegelijk nicotine van de receptor. Bijwerkingen zijn misselijkheid, levendige dromen en slaapstoornissen.</p>","image_url":"","wiki_title":"Varenicline","match":"varenicline","option_only":true},"acamprosaat":{"title":"Acamprosaat","short":"Middel dat de craving (hunkering) naar alcohol vermindert; werkt vermoedelijk via antagonisme van glutamaatreceptoren.","definition":"<p><strong>Acamprosaat</strong> wordt gebruikt om de kans op terugval bij alcoholverslaving te verkleinen door de hunkering (craving) naar alcohol te verminderen. Het werkingsmechanisme berust vermoedelijk op modulatie/antagonisme van glutamaterge (NMDA-)neurotransmissie, waardoor de bij onthouding ontstane glutamaat-overactiviteit wordt gedempt.</p>","image_url":"","wiki_title":"Acamprosate","match":"acamprosaat","option_only":true},"bolle buik (ascites)":{"title":"Ascites","short":"Abnormale ophoping van vocht in de buikholte.","definition":"<p>Ascites is vrij vocht in de peritoneale holte, o.a. door levercirrose, hartfalen of maligniteit (zoals ovariumcarcinoom met peritoneale uitzaaiing).</p>","image_url":"","wiki_title":"Ascites","match":"bolle buik (ascites)","option_only":true},"proliferatieve diabetische retinopathie":{"title":"Diabetische retinopathie","short":"Bij proliferatieve diabetische retinopathie groeien door zuurstofgebrek nieuwe, kwetsbare bloedvaten in het netvlies.","definition":"<p>De niet-proliferatieve vorm geeft microaneurysmata, puntbloedinkjes, harde exsudaten en cotton-wool spots. Bij de <strong>proliferatieve vorm</strong> dreigen glasvochtbloedingen, tractie-netvliesloslating en neovasculair glaucoom. Behandeling met laser en anti-VEGF. Jaarlijkse screening bij diabetes is nodig.</p>","image_url":"","wiki_title":"Diabetic retinopathy","match":"proliferatieve diabetische retinopathie|diabetische retinopathie","option_only":true},"virale conjunctivitis":{"title":"Conjunctivitis","short":"Conjunctivitis is een ontsteking van het bindvlies met een rood oog, waterig, slijmerig of etterig vocht, en een normale visus.","definition":"<p>Een <strong>virale conjunctivitis</strong> (vaak adenovirus) is zeer besmettelijk, met waterig vocht en een gezwollen klier voor het oor. Een bacteriële vorm geeft meer pus en dichtgeplakte ogen; een allergische vorm jeuk. Pijn, lichtschuwheid en verminderde visus wijzen op een ernstigere oorzaak.</p>","image_url":"","wiki_title":"Conjunctivitis","match":"virale conjunctivitis|bacteriële conjunctivitis|allergische conjunctivitis","option_only":true},"diverticulosis/itis":{"title":"Diverticulose en diverticulitis","short":"Bij diverticulose zijn er uitstulpingen van het slijmvlies door de wand van het colon; als zo'n divertikel ontsteekt, heet het diverticulitis.","definition":"<p><strong>Diverticulose</strong> komt in westerse landen vooral voor in het sigmoïd, bij ouderen en bij een vezelarm dieet. Diverticulitis geeft pijn linksonder en koorts; complicaties zijn een abces, perforatie en fistels. Divertikels kunnen ook pijnloos een forse bloeding geven.</p>","image_url":"","wiki_title":"Diverticular disease","match":"diverticulosis/itis|diverticulose|diverticulitis|divertikelbloeding in het colon","option_only":true},"h2-receptor antagonisten":{"title":"H2-receptorantagonisten","short":"H2-receptorantagonisten (zoals famotidine) remmen de zuurproductie in de maag door histaminereceptoren op de pariëtale cellen te blokkeren.","definition":"<p><strong>H2-antagonisten</strong> zijn minder krachtig dan protonpompremmers en worden nog gebruikt bij lichte refluxklachten. Ranitidine is van de markt gehaald vanwege verontreiniging met een kankerverwekkende stof.</p>","image_url":"","wiki_title":"H2 receptor antagonist","match":"h2-receptor antagonisten|h2-antagonist|ranitidine|famotidine","option_only":true},"alcoholische levercirrose":{"title":"Levercirrose","short":"Bij levercirrose is het leverweefsel vervangen door bindweefsel en regeneratieknobbels, met verlies van leverfunctie en portale hypertensie.","definition":"<p>Oorzaken van <strong>cirrose</strong> zijn o.a. alcohol, NASH, chronische hepatitis B en C, auto-immuunziekten en hemochromatose. Gevolgen: ascites, varices met bloedingen, hepatische encefalopathie, icterus, stollingsstoornissen en een verhoogd risico op hepatocellulair carcinoom. Ernst wordt ingedeeld met Child-Pugh of MELD.</p>","image_url":"","wiki_title":"Cirrhosis","match":"alcoholische levercirrose","option_only":true},"antistoffen tegen aquaporine-4":{"title":"Neuromyelitis optica","short":"Neuromyelitis optica is een auto-immuunziekte met ernstige ontsteking van oogzenuwen en ruggenmerg, door antistoffen tegen aquaporine-4.","definition":"<p>Bij <strong>NMO</strong> ontstaan ernstige opticus-neuritiden en een uitgebreide myelitis over drie of meer segmenten, soms een area postrema-syndroom (onbedwingbaar braken en hikken). Het onderscheid met MS is belangrijk, omdat sommige MS-middelen NMO verergeren.</p>","image_url":"","wiki_title":"Neuromyelitis optica","match":"antistoffen tegen aquaporine-4","option_only":true},"neuromyelitis optica spectrum disease":{"title":"Neuromyelitis optica","short":"Neuromyelitis optica is een auto-immuunziekte met ernstige ontsteking van oogzenuwen en ruggenmerg, door antistoffen tegen aquaporine-4.","definition":"<p>Bij <strong>NMO</strong> ontstaan ernstige opticus-neuritiden en een uitgebreide myelitis over drie of meer segmenten, soms een area postrema-syndroom (onbedwingbaar braken en hikken). Het onderscheid met MS is belangrijk, omdat sommige MS-middelen NMO verergeren.</p>","image_url":"","wiki_title":"Neuromyelitis optica","match":"neuromyelitis optica spectrum disease","option_only":true},"hepatitis":{"title":"Hepatitis","short":"Hepatitis is een ontsteking van de lever, door virussen, alcohol, medicatie, auto-immuniteit of stapelingsziekten.","definition":"<p>Bij acute <strong>hepatitis</strong> zijn de transaminasen sterk verhoogd en kan icterus ontstaan. Chronische hepatitis (vooral B en C) kan leiden tot cirrose en levercelkanker.</p>","image_url":"","wiki_title":"Hepatitis","match":"hepatitis","option_only":true},"vlokatrofie bij coeliakie":{"title":"Coeliakie","short":"Coeliakie is een auto-immuunreactie op gluten, met vlokatrofie in de dunne darm en malabsorptie.","definition":"<p>Klachten van <strong>coeliakie</strong> zijn diarree, buikpijn, gewichtsverlies, ijzergebrek en bij kinderen groeiachterstand. Diagnose met anti-tTG-IgA (met totaal IgA) en een dunnedarmbiopt. Behandeling: een levenslang glutenvrij dieet.</p>","image_url":"","wiki_title":"Coeliac disease","match":"vlokatrofie bij coeliakie|coeliakie|glutenintolerantie","option_only":true}};
